const headers = $json.headers || {};
const body = $json.body || $json;
const incomingBinary = $binary || {};
const binaryKeys = Object.keys(incomingBinary);
const audioKey = incomingBinary.data ? 'data' : incomingBinary.file ? 'file' : binaryKeys[0] || '';
const hasBinary = Boolean(audioKey);
const normalizedBinary = hasBinary ? { data: incomingBinary[audioKey] } : {};
const forcedZone = body.forcedZone || headers['x-forced-zone'] || '';
return [{
  json: {
    hasBinary,
    audioKey,
    text: body.text || '',
    forcedZone,
    timezone: body.timezone || headers['x-timezone'] || 'Europe/Warsaw',
    now: body.now || headers['x-now'] || new Date().toISOString()
  },
  binary: normalizedBinary
}];

