const content = $json.output_text || $json.text || $json.choices?.[0]?.message?.content || $json.output?.[0]?.content?.[0]?.text || '{}';
const parsed = typeof content === 'string' ? JSON.parse(content) : content;
const validZones = ['do', 'plan', 'delegate', 'delete'];
const task = parsed.task || {};
if (!validZones.includes(task.zone)) task.zone = 'do';
let transcript = '';
try { transcript = $('Audio Text').item.json.text || ''; } catch (error) {}
if (!transcript) {
  try { transcript = $('Typed Text').item.json.text || ''; } catch (error) {}
}
if (!transcript) transcript = $('Normalize Input').item.json.text || '';
if (!task.title) task.title = transcript || 'Nowe zadanie';
const event = parsed.event || { create: false };
return [{ json: { task, event, transcript } }];

const calendar = $('Google Calendar - Create Event').item?.json || {};
const original = $('Parse JSON').item.json;
return [{ json: { task: { ...original.task, calendarEventId: calendar.id || '', dueAt: original.task.dueAt || original.event.start || '' }, event: original.event, calendar } }];
